.tree-right-box {
    /*position: relative;*/
    width: 100%;
    height: 100%;
}

.tree-wrap {
    width: 100%;
    border-right: 1px solid;
    border-image: linear-gradient(#fafafa, #eaeaea, #fafafa) 50 50;
    z-index: 79;
    padding: 0;
}

.tree-wrap .listName {
    font-family: PingFangSC-Semibold;
    font-weight: 600;
    font-size: 14px;
    color: #333651;
    padding: 12px 28px;
    white-space: nowrap;
    position: relative;
    overflow: hidden;
    width: 100%;
}

.tree-wrap .tree-filter {
    display: flex;
    flex-direction: column;
}

.is-empty {
    line-height: 60px;
    color: #909399;
    width: 100%;
    text-align: center;
    position: relative;
    top: 35%;
}

.tree-wrap .tree-filter ::v-deep .el-input__inner:hover {
    border: 1px solid #2794f8;
    background: #e8eff6;
}

.checkGroup {
    width: 100%;
    height: calc(100% - 135px);
    overflow: auto;
}

.el-checkbox-group {
    width: 100%;
    height: calc(100% - 55px);
}

.process-list {
    width: auto;
    min-width: calc(100% - 48px);
    height: 36px;
    line-height: 36px;
    text-align: left;
    margin: 0 24px !important;
    padding: 0 20px;
}

.allChecked {
    padding: 0 8px;
}

.process-list:hover {
    background: #f5f5f5;
    border-radius: 4px;
    color: #2695f9;
}

.process-list-checked {
    width: auto;
    min-width: calc(100% - 48px);
    height: 36px;
    line-height: 36px;
    text-align: left;
    margin: 0 24px !important;
    border-radius: 8px;
    background: #d9edff;
    padding: 0 20px;
}

.el-checkbox__inner {
    margin-left: 28px !important;
}

.mouseover {
    z-index: 111;
}
